import type {
  AssignmentOption,
  ReasonAssignment,
} from "@/components/openlmis/reason-editor-page/reason-assignment"
import type { ReasonValues } from "@/components/openlmis/reason-editor-page/reason-form"

export type MockReason = {
  values: ReasonValues
  assignments: ReasonAssignment[]
}

export const MOCK_PROGRAMS: AssignmentOption[] = [
  { id: "family-planning", name: "Family Planning" },
  { id: "essential-meds", name: "Essential Meds" },
  { id: "new-program", name: "New Program" },
  { id: "epi", name: "EPI" },
]

/** Every facility type, so a saved row for an inactive one still has a name. */
export const MOCK_FACILITY_TYPES: AssignmentOption[] = [
  { id: "health-center", name: "Health Center" },
  { id: "district-hospital", name: "District Hospital" },
  { id: "district-store", name: "District Store" },
  { id: "warehouse", name: "Warehouse" },
  { id: "dispensary", name: "Dispensary" },
]

/** Only active types are offered for a new row. */
export const MOCK_ACTIVE_FACILITY_TYPES = MOCK_FACILITY_TYPES.filter(
  (type) => type.id !== "dispensary"
)

/** Tags other reasons use, suggested as the user types. */
export const MOCK_TAGS = [
  "adjustment",
  "consumed",
  "damaged",
  "expired",
  "receipts",
]

/** Names other reasons already have. */
export const MOCK_TAKEN_NAMES = ["Transfer Out", "Damage", "Expired", "Stolen"]

export const MOCK_REASON: MockReason = {
  values: {
    name: "Transfer In",
    category: "TRANSFER",
    type: "CREDIT",
    isFreeTextAllowed: false,
    tags: ["receipts"],
  },
  assignments: [
    {
      programId: "family-planning",
      facilityTypeId: "health-center",
      show: true,
    },
    { programId: "family-planning", facilityTypeId: "dispensary", show: false },
    {
      programId: "essential-meds",
      facilityTypeId: "district-hospital",
      show: true,
    },
  ],
}

"use client"

import { revalidateLogic } from "@tanstack/react-form"
import { useMemo, useState } from "react"

import { Field, FieldGroup, FieldLabel } from "@/components/ui/field"
import {
  FormDialog,
  FormDialogBody,
  FormDialogCancel,
  FormDialogDescription,
  FormDialogFooter,
  FormDialogForm,
  FormDialogHeader,
  FormDialogSubmit,
  FormDialogTitle,
} from "@/components/openlmis/form-dialog/form-dialog"
import { useDialogTarget } from "@/components/openlmis/form-dialog/use-dialog-target"
import { useAppForm } from "@/components/openlmis/form-fields/form"
import { FieldSkeleton } from "@/components/openlmis/form-fields/form-fields"

import {
  addAssignmentSchema,
  type AssignmentOption,
  EMPTY_ASSIGNMENT,
  type ReasonAssignment,
} from "@/components/openlmis/reason-editor-page/reason-assignment"

type ReasonAssignmentDialogProps = {
  open: boolean
  /** The reason's assignments, so a pair already listed is refused. */
  rows: readonly ReasonAssignment[]
  /** The programs and active facility types to pick from; skeletons show until set. */
  programs: readonly AssignmentOption[] | undefined
  facilityTypes: readonly AssignmentOption[] | undefined
  /** Called with the new assignment; add it, then close. */
  onAdd: (assignment: ReasonAssignment) => void
  onClose: () => void
}

/** Offer a reason for one more program and facility type. */
export function ReasonAssignmentDialog({
  open,
  onClose,
  ...props
}: ReasonAssignmentDialogProps) {
  const { shown, dialogProps } = useDialogTarget(open || undefined, onClose)

  return (
    <FormDialog {...dialogProps()}>
      {shown && <AddAssignmentContent {...props} />}
    </FormDialog>
  )
}

function AddAssignmentHeader() {
  return (
    <FormDialogHeader>
      <FormDialogTitle>Add Program And Facility Type</FormDialogTitle>
      <FormDialogDescription>
        Offer this reason for one more program and facility type.
      </FormDialogDescription>
    </FormDialogHeader>
  )
}

type ContentProps = Omit<ReasonAssignmentDialogProps, "open" | "onClose">

function AddAssignmentContent({
  programs,
  facilityTypes,
  ...props
}: ContentProps) {
  if (!programs || !facilityTypes) {
    return (
      <>
        <AddAssignmentHeader />
        <FormDialogBody>
          <div aria-busy>
            <FieldGroup>
              <FieldSkeleton label="Program" required />
              <FieldSkeleton label="Facility Type" required />
              <Field orientation="horizontal">
                <div className="flex min-h-8 flex-1 items-center">
                  <FieldLabel>Show</FieldLabel>
                </div>
                {/* A plain element, since Skeleton owns its corner radius and the switch is round. */}
                <div className="h-4.5 w-8 shrink-0 animate-pulse rounded-full bg-muted" />
              </Field>
            </FieldGroup>
          </div>
        </FormDialogBody>
        <FormDialogFooter>
          <FormDialogCancel />
          <FormDialogSubmit disabled>Add</FormDialogSubmit>
        </FormDialogFooter>
      </>
    )
  }
  return (
    <AddAssignmentForm
      facilityTypes={facilityTypes}
      programs={programs}
      {...props}
    />
  )
}

const byLabel = (a: { label: string }, b: { label: string }) =>
  a.label.localeCompare(b.label)

const toItems = (options: readonly AssignmentOption[]) =>
  options
    .map((item) => ({ value: item.id, label: item.name }))
    // oxlint-disable-next-line unicorn/no-array-sort -- sorts the new array without requiring ES2023
    .sort(byLabel)

function AddAssignmentForm({
  rows,
  programs,
  facilityTypes,
  onAdd,
}: Omit<ContentProps, "programs" | "facilityTypes"> & {
  programs: readonly AssignmentOption[]
  facilityTypes: readonly AssignmentOption[]
}) {
  // The rows as the dialog opened, so the pair just added is not refused while it closes.
  const [rowsAtOpen] = useState(rows)
  const programItems = useMemo(() => toItems(programs), [programs])
  const typeItems = useMemo(() => toItems(facilityTypes), [facilityTypes])
  const schema = useMemo(() => addAssignmentSchema(rowsAtOpen), [rowsAtOpen])

  const form = useAppForm({
    defaultValues: EMPTY_ASSIGNMENT,
    // Quiet until the first submit, then each field re-checks as it is corrected.
    validationLogic: revalidateLogic({
      mode: "submit",
      modeAfterSubmission: "change",
    }),
    validators: { onDynamic: schema },
    onSubmit: ({ value }) => onAdd(value),
  })

  return (
    <FormDialogForm onSubmit={() => void form.handleSubmit()}>
      <AddAssignmentHeader />
      <FormDialogBody>
        <FieldGroup>
          <form.AppField name="programId">
            {(field) => (
              <field.SelectField
                items={programItems}
                label="Program"
                required
              />
            )}
          </form.AppField>
          <form.AppField name="facilityTypeId">
            {(field) => (
              <field.SelectField
                items={typeItems}
                label="Facility Type"
                required
              />
            )}
          </form.AppField>
          <form.AppField name="show">
            {(field) => (
              <field.SwitchField
                description="Show the reason in the requisition and stock adjustment forms."
                label="Show"
              />
            )}
          </form.AppField>
        </FieldGroup>
      </FormDialogBody>
      <FormDialogFooter>
        <FormDialogCancel />
        <FormDialogSubmit>Add</FormDialogSubmit>
      </FormDialogFooter>
    </FormDialogForm>
  )
}

import { z } from "zod"

/** A program or facility type: picked by id and shown by name. */
export type AssignmentOption = {
  id: string
  name: string
}

/** Where a reason is offered; `show` false keeps it assigned but out of the stock and requisition forms. */
export type ReasonAssignment = {
  programId: string
  facilityTypeId: string
  show: boolean
}

export type AssignmentRef = Pick<
  ReasonAssignment,
  "programId" | "facilityTypeId"
>

export const assignmentKey = (ref: AssignmentRef) =>
  `${ref.programId}|${ref.facilityTypeId}`

/** The same program and facility type can be listed once, whatever its Show. */
export function addAssignmentSchema(rows: readonly AssignmentRef[]) {
  const listed = new Set(rows.map(assignmentKey))
  return z
    .object({
      programId: z.string().min(1, "Choose a program."),
      facilityTypeId: z.string().min(1, "Choose a facility type."),
      show: z.boolean(),
    })
    .refine((pair) => !listed.has(assignmentKey(pair)), {
      message: "This program and facility type are already listed.",
      path: ["facilityTypeId"],
    })
}

export const EMPTY_ASSIGNMENT: ReasonAssignment = {
  programId: "",
  facilityTypeId: "",
  show: true,
}

/** Names an assignment's program and facility type; an unknown id shows as Unknown. */
export function assignmentNames(
  programs: readonly AssignmentOption[],
  facilityTypes: readonly AssignmentOption[]
) {
  const programNames = new Map(programs.map((item) => [item.id, item.name]))
  const typeNames = new Map(facilityTypes.map((item) => [item.id, item.name]))
  const program = (id: string) => programNames.get(id) ?? "Unknown"
  const facilityType = (id: string) => typeNames.get(id) ?? "Unknown"
  return {
    program,
    facilityType,
    pair: (ref: AssignmentRef) =>
      `${program(ref.programId)}, ${facilityType(ref.facilityTypeId)}`,
  }
}

"use client"

import { MapPinnedIcon, PlusIcon, Trash2Icon } from "lucide-react"
import { useMemo, useRef, useState } from "react"

import { Button } from "@/components/ui/button"
import {
  Empty,
  EmptyDescription,
  EmptyHeader,
  EmptyMedia,
  EmptyTitle,
} from "@/components/ui/empty"
import { Skeleton } from "@/components/ui/skeleton"
import { Switch } from "@/components/ui/switch"
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table"
import { DataTableCard } from "@/components/blocks/openlmis/data-table/data-table"
import {
  type AssignmentOption,
  assignmentKey,
  assignmentNames,
  type ReasonAssignment,
} from "@/components/openlmis/reason-editor-page/reason-assignment"
import { ReasonAssignmentDialog } from "@/components/openlmis/reason-editor-page/reason-assignment-dialog"

type ReasonAssignmentsProps = {
  /** Where the reason is offered; a skeleton shows until it is set. */
  rows: readonly ReasonAssignment[] | undefined
  /** Name the rows; a missing id shows as Unknown. */
  programs: readonly AssignmentOption[] | undefined
  /** Every facility type, naming the rows, including ones no longer active. */
  facilityTypes: readonly AssignmentOption[] | undefined
  /** The facility types Add offers; defaults to `facilityTypes`. */
  activeFacilityTypes?: readonly AssignmentOption[] | undefined
  /** Called with the rows after any change; keep them until the page saves. */
  onRowsChange: (rows: ReasonAssignment[]) => void
  readOnly?: boolean
}

const NO_OPTIONS: readonly AssignmentOption[] = []

/** The programs and facility types a reason is offered for, with Show and Remove. */
export function ReasonAssignments({
  rows,
  programs,
  facilityTypes,
  activeFacilityTypes = facilityTypes,
  onRowsChange,
  readOnly = false,
}: ReasonAssignmentsProps) {
  const table = useRef<HTMLDivElement>(null)
  const addButton = useRef<HTMLButtonElement>(null)
  const [adding, setAdding] = useState(false)
  const names = useMemo(
    () => assignmentNames(programs ?? NO_OPTIONS, facilityTypes ?? NO_OPTIONS),
    [programs, facilityTypes]
  )

  if (!rows || !programs || !facilityTypes) {
    return <ReasonAssignmentsSkeleton readOnly={readOnly} rows={rows?.length} />
  }

  const remove = (index: number) => {
    onRowsChange(rows.filter((_, at) => at !== index))
    // The pressed button is gone, so the next row's takes the focus, or Add.
    requestAnimationFrame(() => {
      const buttons =
        table.current?.querySelectorAll<HTMLElement>("[data-remove-pair]")
      const next = buttons?.[Math.min(index, buttons.length - 1)]
      ;(next ?? addButton.current)?.focus()
    })
  }

  return (
    <div className="flex flex-col gap-4">
      {!readOnly && (
        <div className="flex justify-end">
          <Button
            onClick={() => setAdding(true)}
            ref={addButton}
            variant="outline"
          >
            <PlusIcon data-icon="inline-start" />
            Add Program And Facility Type
          </Button>
        </div>
      )}
      <ReasonAssignmentDialog
        facilityTypes={activeFacilityTypes}
        onAdd={(row) => {
          onRowsChange([...rows, row])
          setAdding(false)
        }}
        onClose={() => setAdding(false)}
        open={adding}
        programs={programs}
        rows={rows}
      />
      <div ref={table}>
        <DataTableCard>
          {rows.length === 0 ? (
            <AssignmentsEmpty />
          ) : (
            <Table>
              <AssignmentsHeader />
              <TableBody>
                {rows.map((row, index) => {
                  const pair = names.pair(row)
                  return (
                    <TableRow key={assignmentKey(row)}>
                      <TableCell>
                        <span
                          className="font-medium whitespace-normal"
                          dir="auto"
                        >
                          {names.program(row.programId)}
                        </span>
                      </TableCell>
                      <TableCell>
                        <span className="whitespace-normal" dir="auto">
                          {names.facilityType(row.facilityTypeId)}
                        </span>
                      </TableCell>
                      <TableCell>
                        <Switch
                          aria-label={`Show For ${pair}`}
                          checked={row.show}
                          disabled={readOnly}
                          onCheckedChange={(show) =>
                            onRowsChange(
                              rows.map((item, at) =>
                                at === index ? { ...item, show } : item
                              )
                            )
                          }
                        />
                      </TableCell>
                      <TableCell>
                        {!readOnly && (
                          <div className="flex justify-end">
                            <Button
                              aria-label={`Remove ${pair}`}
                              data-remove-pair
                              onClick={() => remove(index)}
                              size="icon-sm"
                              variant="destructive"
                            >
                              <Trash2Icon />
                            </Button>
                          </div>
                        )}
                      </TableCell>
                    </TableRow>
                  )
                })}
              </TableBody>
            </Table>
          )}
        </DataTableCard>
      </div>
    </div>
  )
}

function AssignmentsEmpty() {
  return (
    <Empty>
      <EmptyHeader>
        <EmptyMedia variant="icon">
          <MapPinnedIcon />
        </EmptyMedia>
        <EmptyTitle>Not Offered Anywhere Yet</EmptyTitle>
        <EmptyDescription>
          Add a program and facility type to offer this reason there.
        </EmptyDescription>
      </EmptyHeader>
    </Empty>
  )
}

function AssignmentsHeader() {
  return (
    <TableHeader>
      <TableRow>
        <TableHead>Program</TableHead>
        <TableHead>Facility Type</TableHead>
        <TableHead>Show</TableHead>
        <TableHead>
          <span className="sr-only">Actions</span>
        </TableHead>
      </TableRow>
    </TableHeader>
  )
}

/** As many placeholder rows as the reason has, or the empty state for none. */
function ReasonAssignmentsSkeleton({
  rows = 3,
  readOnly,
}: {
  rows?: number | undefined
  readOnly: boolean
}) {
  return (
    <div aria-busy className="flex flex-col gap-4">
      {!readOnly && (
        <div className="flex justify-end">
          <Button disabled variant="outline">
            <PlusIcon data-icon="inline-start" />
            Add Program And Facility Type
          </Button>
        </div>
      )}
      <DataTableCard>
        {rows === 0 ? (
          <AssignmentsEmpty />
        ) : (
          <Table>
            <AssignmentsHeader />
            <TableBody>
              {Array.from({ length: rows }, (_, index) => (
                // Placeholder rows have nothing else to key on.
                <TableRow key={index}>
                  <TableCell>
                    <Skeleton className="h-4 w-28" />
                  </TableCell>
                  <TableCell>
                    <Skeleton className="h-4 w-24" />
                  </TableCell>
                  <TableCell>
                    <div className="h-4.5 w-8 animate-pulse rounded-full bg-muted" />
                  </TableCell>
                  <TableCell>
                    <div className="flex justify-end">
                      <Skeleton className="size-7" />
                    </div>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        )}
      </DataTableCard>
    </div>
  )
}

"use client"

import { AlertCircleIcon, MessageSquareTextIcon } from "lucide-react"
import { useEffect, useMemo, useRef, useState } from "react"

import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert"
import { Button } from "@/components/ui/button"
import { FieldDescription, FieldLegend, FieldSet } from "@/components/ui/field"
import { Spinner } from "@/components/ui/spinner"
import {
  assignmentKey,
  assignmentNames,
  type ReasonAssignment,
} from "@/components/openlmis/reason-editor-page/reason-assignment"
import { ReasonAssignments } from "@/components/openlmis/reason-editor-page/reason-assignments"
import {
  EMPTY_REASON,
  type ReasonValues,
} from "@/components/openlmis/reason-editor-page/reason-form"
import { ReasonGeneralForm } from "@/components/openlmis/reason-editor-page/reason-general-form"
import {
  Workspace,
  WorkspaceContent,
  WorkspaceDescription,
  WorkspaceFooter,
  WorkspaceHeader,
  WorkspaceHeading,
  WorkspaceIcon,
  WorkspaceLayout,
  WorkspaceTitle,
} from "@/components/blocks/openlmis/workspace"
import { Callout } from "@/components/openlmis/callout"
import { DiscardChangesDialog } from "@/components/openlmis/discard-changes-dialog"
import { PageBreadcrumbs } from "@/components/openlmis/page-breadcrumbs"

import {
  MOCK_ACTIVE_FACILITY_TYPES,
  MOCK_FACILITY_TYPES,
  MOCK_PROGRAMS,
  MOCK_REASON,
  MOCK_TAGS,
  MOCK_TAKEN_NAMES,
  type MockReason,
} from "@/components/openlmis/reason-editor-page/mock-reason"

const FORM_ID = "reason-form"

type ReasonEditorPageProps = {
  /** Start on a new, empty reason. */
  adding?: boolean
  /** Show the skeleton, as while the reason loads. */
  loading?: boolean
  /** Show Save as in progress. */
  pending?: boolean
  /** Mock outcome: every save fails. */
  saveFails?: boolean
  /** Mock outcome: the server refuses any changed name. */
  refuseNames?: boolean
  /** Mock outcome: the reason saves, but its new or changed places do not. */
  placesFail?: boolean
}

const NEW_REASON: MockReason = { values: EMPTY_REASON, assignments: [] }

const LOOKUPS = { tags: MOCK_TAGS }

const NAMES = assignmentNames(MOCK_PROGRAMS, MOCK_FACILITY_TYPES)

/** Rows that are new, or whose Show changed, since the last save. */
function unsavedAssignments(
  rows: readonly ReasonAssignment[],
  saved: readonly ReasonAssignment[]
) {
  const stored = new Map(saved.map((row) => [assignmentKey(row), row]))
  return rows.filter((row) => stored.get(assignmentKey(row))?.show !== row.show)
}

const sameAssignments = (
  rows: readonly ReasonAssignment[],
  saved: readonly ReasonAssignment[]
) =>
  rows.length === saved.length && unsavedAssignments(rows, saved).length === 0

type Notice = { title: string; description: string }

/** Focuses the first invalid field, waiting for it to render if needed. */
function focusFirstError(container: HTMLElement) {
  const focus = () => {
    const field = container.querySelector<HTMLElement>('[aria-invalid="true"]')
    field?.focus()
    return Boolean(field)
  }
  if (focus()) return () => {}
  const observer = new MutationObserver(() => {
    if (focus()) observer.disconnect()
  })
  observer.observe(container, {
    attributes: true,
    attributeFilter: ["aria-invalid"],
    childList: true,
    subtree: true,
  })
  return () => observer.disconnect()
}

/** Add or edit a stock reason: why stock moves, and where the reason is offered. */
export function ReasonEditorPage({
  adding: startAdding = false,
  loading = false,
  pending = false,
  saveFails = false,
  refuseNames = false,
  placesFail = false,
}: ReasonEditorPageProps) {
  const [adding, setAdding] = useState(startAdding)
  const [saved, setSaved] = useState(startAdding ? NEW_REASON : MOCK_REASON)
  // Bumped to start the form again from `saved`, after a save or a discard.
  const [revision, setRevision] = useState(0)
  const [assignments, setAssignments] = useState(saved.assignments)
  const [formChanges, setFormChanges] = useState(0)
  const [refusedNames, setRefusedNames] = useState<string[]>([])
  const [saveError, setSaveError] = useState(false)
  const [notSaved, setNotSaved] = useState<ReasonAssignment[]>([])
  const [notice, setNotice] = useState<Notice>()
  const [discarding, setDiscarding] = useState(false)
  // Bumped to focus the first error after a refused or invalid submit.
  const [focusRequest, setFocusRequest] = useState(0)
  const container = useRef<HTMLDivElement>(null)
  const changes =
    formChanges + (sameAssignments(assignments, saved.assignments) ? 0 : 1)
  const takenNames = useMemo(
    () => [
      ...MOCK_TAKEN_NAMES.filter((name) => name !== saved.values.name),
      ...refusedNames,
    ],
    [saved.values.name, refusedNames]
  )

  useEffect(() => {
    if (focusRequest === 0 || !container.current) return
    return focusFirstError(container.current)
  }, [focusRequest])

  const requestFocus = () => setFocusRequest((current) => current + 1)

  const start = (reason: MockReason) => {
    setSaved(reason)
    setAssignments(reason.assignments)
    setRevision((current) => current + 1)
    setFormChanges(0)
    setRefusedNames([])
    setSaveError(false)
    setNotSaved([])
    setNotice(undefined)
  }

  const save = (values: ReasonValues) => {
    setSaveError(false)
    setNotSaved([])
    setNotice(undefined)
    if (saveFails) {
      setSaveError(true)
      return
    }
    if (refuseNames && values.name !== saved.values.name) {
      // The server refused the name, so the form now marks it as taken.
      setRefusedNames((names) => [...names, values.name])
      requestFocus()
      return
    }
    const unsaved = unsavedAssignments(assignments, saved.assignments)
    if (placesFail && unsaved.length > 0) {
      // The reason saved, but its new places did not; Save again retries them.
      const failed = new Set(unsaved.map(assignmentKey))
      setSaved({
        values,
        assignments: [
          ...saved.assignments.filter((row) =>
            assignments.some(
              (draft) => assignmentKey(draft) === assignmentKey(row)
            )
          ),
          ...assignments.filter(
            (row) =>
              !failed.has(assignmentKey(row)) &&
              !saved.assignments.some(
                (stored) => assignmentKey(stored) === assignmentKey(row)
              )
          ),
        ],
      })
      // The form starts again from the saved values; the failed places stay as drafts.
      setRevision((current) => current + 1)
      setFormChanges(0)
      setNotSaved(unsaved)
      setAdding(false)
      return
    }
    const wasAdding = adding
    start({ values, assignments })
    setAdding(false)
    setNotice(
      wasAdding
        ? {
            title: "Reason Created",
            description: `${values.name} is ready to use.`,
          }
        : {
            title: "Reason Saved",
            description: `Changes to ${values.name} are saved.`,
          }
    )
  }

  const cancel = () => {
    if (changes > 0) setDiscarding(true)
    else start(saved)
  }

  return (
    <WorkspaceLayout ref={container}>
      <Workspace width="narrow">
        <PageBreadcrumbs
          items={[
            { label: "Home", href: "#" },
            { label: "Administration" },
            { label: "Reasons", href: "#" },
            { label: adding ? "Add Reason" : "Edit Reason" },
          ]}
        />
        <WorkspaceHeader>
          <WorkspaceHeading>
            <WorkspaceIcon>
              <MessageSquareTextIcon />
            </WorkspaceIcon>
            <WorkspaceTitle>
              {adding
                ? "Add Reason"
                : loading
                  ? "Edit Reason"
                  : `Edit ${saved.values.name}`}
            </WorkspaceTitle>
            <WorkspaceDescription>
              {adding
                ? "Say why stock moves, and where the reason is offered."
                : "Change the reason's name, tags and where it is offered."}
            </WorkspaceDescription>
          </WorkspaceHeading>
        </WorkspaceHeader>
        <WorkspaceContent>
          <div className="flex flex-col gap-8" inert={pending}>
            {(notice || saveError || notSaved.length > 0) && (
              <div className="flex flex-col gap-4">
                {notice && (
                  <Callout title={notice.title} tone="success">
                    {notice.description}
                  </Callout>
                )}
                {saveError && (
                  <Alert variant="destructive">
                    <AlertCircleIcon />
                    <AlertTitle>Could Not Save Reason</AlertTitle>
                    <AlertDescription>
                      Something went wrong. Check your connection and try again.
                    </AlertDescription>
                  </Alert>
                )}
                {notSaved.length > 0 && (
                  <Alert variant="destructive">
                    <AlertCircleIcon />
                    <AlertTitle>Some Places Not Saved</AlertTitle>
                    <AlertDescription>
                      The reason is saved, but these places are not:{" "}
                      {notSaved.map(NAMES.pair).join("; ")}. Save again to try
                      them once more.
                    </AlertDescription>
                  </Alert>
                )}
              </div>
            )}
            <ReasonGeneralForm
              formId={FORM_ID}
              key={revision}
              lookups={LOOKUPS}
              onChangesChange={setFormChanges}
              onInvalid={requestFocus}
              onSubmit={save}
              reason={loading ? undefined : saved.values}
              saved={!adding}
              takenNames={takenNames}
            />
            <FieldSet>
              <FieldLegend>Where Is This Reason Used?</FieldLegend>
              <FieldDescription>
                Add each program and facility type where this reason can be
                used, and whether to show it in the requisition and stock
                adjustment forms.
              </FieldDescription>
              <ReasonAssignments
                activeFacilityTypes={MOCK_ACTIVE_FACILITY_TYPES}
                facilityTypes={loading ? undefined : MOCK_FACILITY_TYPES}
                onRowsChange={setAssignments}
                programs={loading ? undefined : MOCK_PROGRAMS}
                rows={assignments}
              />
            </FieldSet>
          </div>
        </WorkspaceContent>
      </Workspace>
      <WorkspaceFooter width="narrow">
        <Button
          disabled={pending || loading}
          onClick={cancel}
          size="lg"
          variant="outline"
        >
          Cancel
        </Button>
        <Button
          disabled={pending || loading}
          focusableWhenDisabled={pending}
          form={FORM_ID}
          size="lg"
          type="submit"
        >
          {pending && <Spinner data-icon="inline-start" />}
          {adding ? "Create" : "Save"}
        </Button>
      </WorkspaceFooter>
      <DiscardChangesDialog
        changes={changes}
        onDiscard={() => {
          setDiscarding(false)
          start(saved)
        }}
        onKeepEditing={() => setDiscarding(false)}
        open={discarding}
        subject={adding ? "the new reason" : saved.values.name}
      />
    </WorkspaceLayout>
  )
}

